const { test, expect } = require('@playwright/test');
const {
    deleteRepository,
    memoryRepositoryConfiguration,
    openQueryPage,
    repositoryPageUrl,
    runQuery,
    serverBaseUrl,
    uniqueRepositoryId,
    waitForRoute
} = require('./workbench-test-helpers.js');

// The Graph page starts empty, keeps its graph in the browser, and takes what "Add to graph" on the other Workbench
// pages sends it: a resource from Explore with its neighbours, or the results of a query.
const REPOSITORY_ID = uniqueRepositoryId('graph-store');
const ALICE = 'http://example.org/store/alice';
const DATA = `
@prefix ex: <http://example.org/store/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
ex:alice a ex:Person ; rdfs:label "Alice" ; ex:knows ex:bob .
ex:bob a ex:Person ; rdfs:label "Bob" ; ex:worksFor ex:acme .
ex:acme a ex:Organization ; rdfs:label "Acme" .
`;

test.beforeAll(async ({ request }) => {
    const repositoryUrl = `${serverBaseUrl()}/repositories/${REPOSITORY_ID}`;
    const created = await request.put(repositoryUrl, {
        headers: { 'Content-Type': 'text/turtle' },
        data: memoryRepositoryConfiguration(REPOSITORY_ID, 'Graph store')
    });
    expect([200, 201, 204]).toContain(created.status());
    const loaded = await request.post(`${repositoryUrl}/statements`, {
        headers: { 'Content-Type': 'text/turtle' },
        data: DATA
    });
    expect([200, 204]).toContain(loaded.status());
});

test.afterAll(async ({ request }) => {
    await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

function node(explorer, label) {
    return explorer.locator('.graph-node').filter({ has: explorer.page().locator('text', { hasText: label }) }).first();
}

async function openGraphPage(page) {
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'));
    await waitForRoute(page, 'graph');
    return page.locator('.graph-explorer');
}

/** The graph the Graph page keeps for the repository in the browser's database (see workspace-storage.ts). */
function storedGraph(page) {
    return page.evaluate((repositoryId) => new Promise((resolve, reject) => {
        const app = document.getElementById('workbench-app');
        const basePath = app?.getAttribute('data-workbench-base-path');
        const serverIdentity = app?.getAttribute('data-workbench-server-identity');
        if (!basePath || !serverIdentity) {
            resolve('');
            return;
        }
        const scope = JSON.stringify(['repository-v2', basePath.replace(/\/+$/, ''), serverIdentity, repositoryId]);
        const key = `workspace:${scope}`;
        const request = indexedDB.open('graph-field-workspaces');
        request.onupgradeneeded = () => {
            if (!request.result.objectStoreNames.contains('workspaces')) request.result.createObjectStore('workspaces');
        };
        request.onerror = () => reject(request.error);
        request.onsuccess = () => {
            const db = request.result;
            db.onversionchange = () => db.close();
            if (!db.objectStoreNames.contains('workspaces')) {
                db.close();
                resolve('');
                return;
            }
            try {
                const transaction = db.transaction('workspaces');
                const read = transaction.objectStore('workspaces').get(key);
                let raw = '';
                read.onsuccess = () => { raw = typeof read.result === 'string' ? read.result : ''; };
                read.onerror = () => { db.close(); reject(read.error); };
                transaction.oncomplete = () => { db.close(); resolve(raw); };
                transaction.onerror = transaction.onabort = () => {
                    db.close();
                    reject(transaction.error ?? new Error('Reading the stored graph was aborted.'));
                };
            } catch (error) {
                db.close();
                reject(error);
            }
        };
    }), REPOSITORY_ID);
}

async function addAliceFromExplore(page) {
    await page.goto(`${repositoryPageUrl(REPOSITORY_ID, 'explore')}?resource=${encodeURIComponent(`<${ALICE}>`)}`);
    await waitForRoute(page, 'explore');
    await page.getByRole('button', { name: 'Add to graph' }).first().click();
    return page.getByRole('link', { name: 'Open graph' });
}

test.beforeEach(async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
});

test('the Graph page starts empty; a resource added on Explore comes with its neighbours and stays after a reload',
    async ({ page }) => {
        const explorer = await openGraphPage(page);
        await expect(explorer.locator('.empty-state h3')).toHaveText('The graph is empty');
        await expect(explorer.locator('.graph-node')).toHaveCount(0);

        const open = await addAliceFromExplore(page);
        await open.click();
        await waitForRoute(page, 'graph');
        await expect(node(explorer, 'Alice')).toBeAttached({ timeout: 30000 });
        await expect(node(explorer, 'Bob')).toBeAttached();
        await expect(explorer.locator('.graph-stats')).toHaveText('2 nodes · 1 link');
        await expect(node(explorer, 'Alice')).toHaveClass(/is-focused/);

        // Stored in the compact form (workspace-format.ts): the label is the second member of the node's tuple.
        await expect.poll(() => storedGraph(page), { timeout: 10000 }).toContain('"Alice"');
        await page.reload();
        await waitForRoute(page, 'graph');
        await expect(node(explorer, 'Alice')).toBeAttached({ timeout: 30000 });
        await expect(explorer.locator('.graph-stats')).toHaveText('2 nodes · 1 link');
        await expect(explorer.locator('.empty-state')).toHaveCount(0);

        await explorer.locator('summary[aria-label="Open workspace tools"]').click();
        await explorer.getByRole('button', { name: 'Clear graph' }).click();
        await expect(explorer.locator('.empty-state h3')).toHaveText('The graph is empty');
        await explorer.getByRole('button', { name: 'Undo the last graph change' }).click();
        await expect(explorer.locator('.graph-stats')).toHaveText('2 nodes · 1 link');
        await explorer.getByRole('button', { name: 'Redo the last undone graph change' }).click();
        await expect(explorer.locator('.empty-state h3')).toHaveText('The graph is empty');
        await expect.poll(() => storedGraph(page), { timeout: 10000 }).toContain('"nodes":[]');
        await page.reload();
        await waitForRoute(page, 'graph');
        await expect(explorer.locator('.empty-state h3')).toHaveText('The graph is empty', { timeout: 30000 });
    });

test('Add to graph on the Query page adds the statements of a CONSTRUCT query', async ({ page }) => {
    await openQueryPage(page, REPOSITORY_ID, { viewport: false });
    await runQuery(page, 'PREFIX ex: <http://example.org/store/> CONSTRUCT { ?s ex:worksFor ?o } WHERE { ?s ex:worksFor ?o }');
    await page.getByRole('button', { name: 'Add the results to the graph' }).click();
    await expect(page.locator('.query-result-add-to-graph')).toContainText('Added to graph');

    const explorer = await openGraphPage(page);
    await expect(node(explorer, 'Bob')).toBeAttached({ timeout: 30000 });
    await expect(node(explorer, 'Acme')).toBeAttached();
    await expect(explorer.locator('.graph-stats')).toHaveText('2 nodes · 1 link');
});

test('a Graph page open in another tab takes the additions as they are made', async ({ page, context }) => {
    const explorer = await openGraphPage(page);
    await expect(explorer.locator('.empty-state')).toBeVisible();

    const other = await context.newPage();
    await other.setViewportSize({ width: 1440, height: 900 });
    await expect(await addAliceFromExplore(other)).toBeVisible();

    await expect(node(explorer, 'Alice')).toBeAttached({ timeout: 30000 });
    await expect(node(explorer, 'Bob')).toBeAttached();
    await other.close();
});

test('Find shows a loaded node, and its last choice searches the repository and adds what it finds', async ({ page }) => {
    const explorer = await openGraphPage(page);
    const find = explorer.getByRole('combobox', { name: /Find a node/ });
    await find.fill('Acme');
    await expect(explorer.getByRole('option')).toHaveText(['Search the repository for “Acme”']);
    await find.press('Enter');
    await expect(node(explorer, 'Acme')).toBeAttached({ timeout: 30000 });

    await find.fill('bo');
    await expect(explorer.getByRole('option')).toHaveText(['Search the repository for “bo”']);
    await explorer.getByRole('option', { name: /Search the repository/ }).click();
    await expect(node(explorer, 'Bob')).toBeAttached({ timeout: 30000 });
    await expect(node(explorer, 'Acme')).toBeAttached();

    await find.fill('acm');
    await expect(explorer.getByRole('option').first()).toContainText('Acme');
    await find.press('Enter');
    await expect(explorer.locator('.node-details h3')).toHaveText('Acme');
});

// A repository search chosen while a query runs is not dropped: the choice stays offered, unavailable, until the query
// is done, and then runs.
test('the repository search waits for a running query instead of dropping the choice', async ({ page }) => {
    const explorer = await openGraphPage(page);
    let releaseQueries;
    const queriesHeld = new Promise((resolve) => { releaseQueries = resolve; });
    let holding = true;
    await page.route(new RegExp(`/repositories/${REPOSITORY_ID}/graph$`), async (route) => {
        if (holding && route.request().method() === 'POST') {
            await queriesHeld;
        }
        return route.fallback();
    });
    const find = explorer.getByRole('combobox', { name: /Find a node/ });
    await find.fill('Acme');
    await find.press('Enter');
    await find.fill('bo');
    const search = explorer.getByRole('option', { name: /Search the repository for “bo”/ });
    await expect(search, 'unavailable while the Acme search runs').toHaveAttribute('aria-disabled', 'true');
    await search.click({ force: true });
    await expect(search, 'the choice is kept, not dropped').toBeVisible();

    holding = false;
    releaseQueries();
    await expect(node(explorer, 'Acme')).toBeAttached({ timeout: 30000 });
    await expect(search).not.toHaveAttribute('aria-disabled', 'true');
    await search.click();
    await expect(node(explorer, 'Bob')).toBeAttached({ timeout: 30000 });
});

test('Tools downloads the loaded statements as Turtle and the drawn graph as SVG and PNG', async ({ page }) => {
    const open = await addAliceFromExplore(page);
    await open.click();
    await waitForRoute(page, 'graph');
    const explorer = page.locator('.graph-explorer');
    await expect(node(explorer, 'Bob')).toBeAttached({ timeout: 30000 });

    const download = async (label) => {
        await explorer.locator('summary[aria-label="Open workspace tools"]').click();
        const [file] = await Promise.all([page.waitForEvent('download'), explorer.getByRole('button', { name: label }).click()]);
        const chunks = [];
        for await (const chunk of await file.createReadStream()) chunks.push(chunk);
        return { name: file.suggestedFilename(), body: Buffer.concat(chunks) };
    };

    const turtle = await download('Download Turtle');
    expect(turtle.name).toBe(`${REPOSITORY_ID}-graph.ttl`);
    expect(turtle.body.toString()).toContain(`<${ALICE}> a <http://example.org/store/Person> ;`);
    expect(turtle.body.toString()).toContain('rdfs:label "Alice"');

    const svg = await download('Download SVG image');
    expect(svg.name).toBe(`${REPOSITORY_ID}-graph.svg`);
    expect(svg.body.toString()).toMatch(/^<svg xmlns="http:\/\/www\.w3\.org\/2000\/svg"/);
    expect(svg.body.toString()).toContain('>Alice</text>');
    expect(svg.body.toString()).not.toContain('var(--');

    const png = await download('Download PNG image');
    expect(png.name).toBe(`${REPOSITORY_ID}-graph.png`);
    expect(png.body.subarray(0, 8)).toEqual(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]));
    expect(png.body.length).toBeGreaterThan(2000);
});
